    "services.dronesDesc": "खेत सर्वेक्षण और एरियल मैपिंग के लिए ड्रोन मिशन योजना प्रोटोटाइप।",
    "services.dronesScope": "योजना प्रोटोटाइप; वास्तविक उड़ानों के लिए नियामक अनुमति आवश्यक है।",
    "services.irrigationDesc": "स्वचालित मृदा नमी सेंसर और स्मार्ट सिंचाई नियंत्रण सिमुलेटर।",
