    "account.dangerZone": "அபாய மண்டலம் (Danger Zone)",
    "account.deleteAccount": "கணக்கை நீக்கு",
    "account.deleteDesc": "உங்கள் ஃபார்ம்கல்ச்சர் ஏஐ கணக்கையும் தொடர்புடைய தனிப்பட்ட பண்ணைத் தரவையும் நிரந்தரமாக நீக்கவும். இந்தச் செயலைத் திரும்பப் பெற முடியாது.",
    "account.deleteButton": "எனது கணக்கை நீக்கு",
    "account.dialogTitle": "கணக்கை நிரந்தரமாக நீக்குதல்",
    "account.dialogDesc": "உங்கள் ஃபார்ம்கல்ச்சர் ஏஐ கணக்கை நிரந்தரமாக நீக்க உள்ளீர்கள். இந்த செயல்பாடு உங்கள் பண்ணை நிலங்கள், பயிர் பதிவுகள், இலை நோய் கண்டறிதல் பதிவுகள், பதிவேற்றிய புகைப்படங்கள் மற்றும் சுயவிவரத் தரவை உடனடியாக அழிக்கிறது.",
    "account.dataDeletedNotice": "பின்வரும் தரவுகள் நிரந்தரமாக அழிக்கப்படும்:",
    "account.itemFarms": "பதிவு செய்யப்பட்ட அனைத்து பண்ணை நிலங்கள் மற்றும் மண் விவரங்கள்",
    "account.itemCrops": "செயலில் உள்ள மற்றும் முந்தைய பயிர் சுழற்சிகள்",
    "account.itemPhotos": "பதிவேற்றப்பட்ட அனைத்து இலை புகைப்படங்கள் மற்றும் நோயறிதல் முடிவுகள்",
    "account.itemReviews": "இந்த கணக்கால் எழுதப்பட்ட மதிப்புரைகள் மற்றும் கருத்துகள்",
    "account.retentionExceptions": "சட்டப்பூர்வ விதிவிலக்குகள்: மறைகுறியாக்கப்பட்ட காப்புப்பிரதிகள் ஆவணப்படுத்தப்பட்ட கொள்கைகளின்படி சுழற்சி முறையில் அழிக்கப்படும்.",
    "account.typeDeletePrompt": "உறுதிப்படுத்த DELETE என்று தட்டச்சு செய்யவும்:",
    "account.confirmDelete": "நிரந்தர நீக்கத்தை உறுதிசெய்க",
