    "account.reauthRequired": "சமீபத்திய அங்கீகாரம் தேவை",
    "account.reauthDesc": "பாதுகாப்பிற்காக, உங்கள் கணக்கை நீக்குவதற்கு முன் உங்கள் கடவுச்சொல்லை உறுதிப்படுத்தவும்.",
    "account.enterPassword": "கடவுச்சொல்லை உள்ளிடவும்",
    "account.reauthPassword": "கடவுச்சொல்லுடன் உறுதிசெய்க",
    "account.reauthGoogle": "Google மூலம் மீண்டும் உள்நுழைக",
